<?php
require_once __DIR__ . '/auth.php'; require_login(); require_once __DIR__ . '/monitor_lib.php';
$file='../data/redes_pautas.json'; $items=tvs_read_json_file($file); $df='../data/rascunhos.json';
if(isset($_POST['add'])){ $items[]=['id'=>uniqid('rede_'),'city'=>$_POST['city']??'Região','network'=>$_POST['network']??'Instagram/Facebook','url'=>$_POST['url']??'','notes'=>$_POST['notes']??'','created_at'=>date('c')]; tvs_save_json_file($file,$items); header('Location: redes.php?ok=1'); exit; }
if(isset($_GET['draft'])){ $id=$_GET['draft']; foreach($items as $it){ if(($it['id']??'')===$id){ $drafts=tvs_read_json_file($df); $drafts[]=['id'=>uniqid('draft_'),'city'=>$it['city'],'source'=>$it['network'],'source_type'=>'rede_social','source_url'=>$it['url'],'title'=>'Pauta das redes sociais para apuração','subtitle'=>'Conteúdo encontrado em rede social e enviado para revisão editorial da TV Sumaré.','body'=>"Esta pauta foi cadastrada a partir de uma publicação em rede social.\n\nLink de referência: {$it['url']}\n\nObservações da redação:\n{$it['notes']}\n\nAntes de publicar, confirme as informações com fonte oficial, envolvidos ou documentos. Não copie texto, imagem ou vídeo da publicação original sem autorização.",'category'=>'Cidades','tags'=>['Redes sociais','Pauta','Apuração'],'image'=>'','status'=>'rascunho_apuracao','created_at'=>date('c')]; tvs_save_json_file($df,$drafts); } } header('Location: drafts.php'); exit; }
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Redes sociais</title><link rel="stylesheet" href="admin.css?v=10"></head><body><div class="admin"><aside class="side"><div class="logo"><img src="../assets/logo-tv-sumare.jpeg"><div><b>TV SUMARÉ</b><br><small>Painel</small></div></div><nav class="menu"><a href="index.php">Dashboard</a><a href="monitor.php">Monitor Regional</a><a href="editor-ia.php">Editor IA</a><a class="active" href="redes.php">Redes sociais</a><a href="drafts.php">Rascunhos</a><a href="logout.php">Sair</a></nav></aside><main class="main"><h1>Pautas de Instagram/Facebook</h1><div class="box"><p>Use redes sociais como referência de pauta. O sistema não copia automaticamente o conteúdo; ele cria um rascunho para apuração e revisão.</p><form method="post" class="form"><?=tvs_csrf_field()?><div class="grid2"><div><label>Rede</label><select name="network"><option>Instagram</option><option>Facebook</option><option>YouTube</option><option>WhatsApp recebido</option></select></div><div><label>Cidade</label><input name="city" placeholder="Sumaré"></div></div><label>Link da publicação</label><input name="url" placeholder="https://instagram.com/..."><label>Observações</label><textarea name="notes" rows="5" placeholder="O que chamou atenção? O que precisa checar?"></textarea><button class="btn orange" name="add" value="1">Salvar pauta</button></form></div><?php foreach(array_reverse($items) as $it): ?><div class="box" style="margin-top:12px"><small><?=htmlspecialchars($it['network'])?> • <?=htmlspecialchars($it['city'])?></small><p><?=nl2br(htmlspecialchars($it['notes']))?></p><a class="btn" target="_blank" href="<?=htmlspecialchars($it['url'])?>">Abrir publicação</a> <a class="btn orange" href="?draft=<?=urlencode($it['id'])?>">Criar rascunho para apuração</a></div><?php endforeach; ?></main></div></body></html>
